"use client";
// 界面多语言：zh-CN / en-US。没有第三方库，只是一张字典和一个很小的当前语言存储。
// - t(key, params) 读当前语言的文案；params 用 {name} 占位。
// - <LocaleProvider> 在客户端解析语言并在切换时整棵重挂（key=locale），这样模块级的 t() 也总是最新。
// - 登录前：localStorage "axiomos.locale" → navigator.language；登录后由 AppShell 用 me.member.locale 覆盖。
// 数据自带的名字（状态、步骤、角色、交付物类型、动态摘要……）由后端按语言返回，这里不翻。
import { createContext, createElement, Fragment, useContext, useEffect, useSyncExternalStore, type ReactNode } from "react";

export type Locale = "zh-CN" | "en-US";
export const LOCALES: Locale[] = ["zh-CN", "en-US"];
export const LOCALE_NAMES: Record<Locale, string> = { "zh-CN": "中文", "en-US": "English" };
export const STORAGE_KEY = "axiomos.locale";

