  // 接入链接（ADR 0024）：公开落地页 /connect/、Agent 页的「复制给 Agent 的链接」、向导里的「贴链接给 Agent」
  "onboard.lead": "把下面这条链接贴给你的 Agent，它会带着你完成接入。",
  "onboard.linkLabel": "贴给 Agent 的话",
  "onboard.copyLink": "复制这段话",
  "onboard.prompt": "读一下 {url}，按里面的说明把你自己接入 AxiomOS，需要我做什么就告诉我。",
  "onboard.copied": "已复制。贴给你的 Agent 就行。",
  "onboard.next": "接下来会发生什么",
  "onboard.next1": "它会给你一个验证码。",
  "onboard.next2": "你在网页上确认，并选好给它哪些授权。",
  "onboard.next3": "它把令牌存进自己的配置。",
  "onboard.next4": "它连上来自检，再把结果告诉你。",
  "onboard.self": "我想自己动手",
  "onboard.selfHint": "不让 Agent 代劳也行：在跑它的那台机器上执行这一行。",
  "onboard.selfNote": "把 client 换成 cursor、codex 或 custom，就是别的运行环境。",
  "onboard.manual": "或者在「Agent」页注册一个 Agent，把一次性令牌自己贴进配置。",
  "onboard.manualLink": "去 Agent 页",
  "onboard.presets": "确认时选哪个授权",
  "onboard.presetsHint": "确认页上有四个预设，点一下就填好：写代码的选「开发」，管需求的选「产品」，做测试的选「测试」，只想让它看看的选「只读观察」。拿不准就选「只读观察」，之后随时可以在「Agent」页改。",
  "onboard.faq": "常见问题",
  "onboard.faq1q": "验证码过期了怎么办？",
  "onboard.faq1a": "验证码 15 分钟内有效。过期了让 Agent 重新申请一个就行，什么都不会留下。",
  "onboard.faq2q": "点了拒绝还能重来吗？",
  "onboard.faq2a": "能。拒绝什么都不会创建，让 Agent 再申请一次，这次选对授权。",
  "onboard.faq3q": "打不开确认页？",
  "onboard.faq3a": "确认页要先登录 AxiomOS。没有账号的人确认不了，请组织里有账号的同事帮忙确认——确认的人会成为这个 Agent 的所有者。",
  "onboard.faq4q": "公司内网能用吗？",
  "onboard.faq4a": "Agent 只往外连 AxiomOS，不需要 AxiomOS 连进你的机器。只要你的机器能打开这个网页，就能接入。",
  "onboard.faq5q": "接完显示「执行中」是在干活吗？",
  "onboard.faq5a": "不是。三分钟内说过话的 Agent 都显示「执行中」，刚接完那一下就是它在自检；没活的时候它会变成「可用」。",
  "connect.paste": "贴链接给 Agent",
  "connect.pasteHint": "把下面这段话整段贴给你的 Agent。它会去读那条链接，那是一份写给它看的操作说明，然后带着你走完接入。",
