  // Agent connection wizard (DESIGN.md §21, ADR 0018)
  "agents.connect": "Connect an agent",
  "agents.copyRollout": "Copy the team announcement",
  "agents.rolloutCopied": "Copied. Paste it into your team chat.",
  "agents.rolloutText": "Team — connecting your AI assistant (Claude Code, Cursor or Codex) to AxiomOS takes three steps:\n1. Open {link} and copy the sentence there\n2. Paste it to your AI assistant; it gives you a verification code\n3. Enter the code on the web page, click a grant preset (Developer for coding, Product for requirements, Tester for testing, Read-only just to look), confirm\nAbout two minutes in total. Codes are valid for 15 minutes; if one expires, ask the assistant for a new one.",
