  // Onboarding link (ADR 0024)
  "onboard.lead": "Paste the link below to your agent — it will walk you through connecting.",
  "onboard.linkLabel": "What to paste to your agent",
  "onboard.copyLink": "Copy this",
  "onboard.prompt": "Read {url} and follow it to connect yourself to AxiomOS; tell me whatever you need from me.",
  "onboard.copied": "Copied. Just paste it to your agent.",
  "onboard.next": "What happens next",
