  "onboard.selfNote": "Swap client for cursor, codex or custom to target another runtime.",
  "onboard.manual": "Or register an agent on the Agents page and paste the one-time token into the config yourself.",
  "onboard.manualLink": "Go to Agents",
  "onboard.presets": "Which grants to pick when confirming",
  "onboard.presetsHint": "The confirmation page has four presets, one click fills them in: pick Developer if it writes code, Product if it manages requirements, Tester if it tests, Read-only if you only want it to look. When unsure pick Read-only; you can change it any time on the Agents page.",
  "onboard.faq": "Common questions",
  "onboard.faq1q": "The code expired?",
  "onboard.faq1a": "A code is valid for 15 minutes. Just ask the agent to request a new one; nothing is left behind.",
  "onboard.faq2q": "I clicked deny — can I start over?",
  "onboard.faq2a": "Yes. Denying creates nothing; ask the agent to request again and pick the right grants this time.",
  "onboard.faq3q": "The confirmation page will not open?",
  "onboard.faq3a": "It requires signing in to AxiomOS. Someone without an account cannot confirm; ask a colleague with an account, who then becomes the agent's owner.",
  "onboard.faq4q": "Does it work on the company network?",
  "onboard.faq4a": "The agent only connects out to AxiomOS; AxiomOS never connects into your machine. If your machine can open this page, it can connect.",
  "onboard.faq5q": "It shows “running” right after connecting — is it working on something?",
  "onboard.faq5a": "No. Any agent that spoke within the last three minutes shows as running; right after connecting that is just its self-check. It turns “ready” once idle.",
